# 【算法思路】根据 epsilon 邻域密度阈值扩展核心点连通簇，同时识别稀疏离群噪声点 (-1)。
import numpy as np

# 计算样本间欧氏距离
def euclidean(a, b):
    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)
    return float(np.sqrt(np.sum((a - b) ** 2)))

# 检索半径 eps 内的全部近邻索引
def region_query(X, p_idx, eps):
    X = np.asarray(X, dtype=float)
    return [i for i in range(len(X)) if euclidean(X[p_idx], X[i]) <= eps]

# 通过队列扩展密度可达点形成聚类并统计噪声点数量
def dbscan(X, eps, min_pts):
    X = np.asarray(X, dtype=float)
    labels = [-2] * len(X)
    cluster_id = 0
    for i in range(len(X)):
        if labels[i] != -2:
            continue
        neighbors = region_query(X, i, eps)
        if len(neighbors) < min_pts:
            labels[i] = -1
            continue
        labels[i] = cluster_id
        seed = neighbors[:]
        for q in seed:
            if labels[q] == -2:
                labels[q] = cluster_id
                q_neighbors = region_query(X, q, eps)
                if len(q_neighbors) >= min_pts:
                    seed.extend([n for n in q_neighbors if labels[n] == -2])
        cluster_id += 1
    return {"labels": labels, "n_clusters": cluster_id, "noise": labels.count(-1)}

