# 【算法思路】实现单链接、全链接与平均链接簇间距离度量，自底向上凝聚层次聚类。
import numpy as np

# 计算两点欧氏距离
def euclidean(a, b):
    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)
    return float(np.sqrt(np.sum((a - b) ** 2)))

# 按指定链接准则计算两簇所有点对距离的最小/最大/均值
def cluster_distance(A, B, linkage="single"):
    A, B = np.asarray(A, dtype=float), np.asarray(B, dtype=float)
    dists = [euclidean(a, b) for a in A for b in B]
    if linkage == "single":
        return float(min(dists))
    if linkage == "complete":
        return float(max(dists))
    return float(sum(dists) / len(dists))

# 贪心合并距离最近的两簇直至达到目标簇数
def agglomerative_clustering(X, n_clusters=2, linkage="single"):
    X = np.asarray(X, dtype=float)
    clusters = [[i] for i in range(len(X))]
    while len(clusters) > n_clusters:
        min_dist = float("inf")
        merge_pair = (0, 1)
        for i in range(len(clusters)):
            for j in range(i + 1, len(clusters)):
                d = cluster_distance(X[clusters[i]], X[clusters[j]], linkage)
                if d < min_dist:
                    min_dist = d
                    merge_pair = (i, j)
        i, j = merge_pair
        clusters[i].extend(clusters[j])
        clusters.pop(j)
    labels = np.zeros(len(X), dtype=int)
    for cid, cluster in enumerate(clusters):
        for idx in cluster:
            labels[idx] = cid
    return labels.tolist()

