# 【算法思路】执行自底向上层次凝聚并在每轮合并时记录树状图 (Dendrogram) 的融合高度。
import numpy as np

# 计算欧氏距离
def euclidean(a, b):
    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)
    return float(np.sqrt(np.sum((a - b) ** 2)))

# 按 single/complete/average 计算两簇间距离
def cluster_dist(A, B, linkage):
    dists = [euclidean(a, b) for a in A for b in B]
    if linkage == "single":
        return min(dists)
    if linkage == "complete":
        return max(dists)
    return sum(dists) / len(dists)

# 合并直至保留目标簇数并返回样本分配
def agglomerative(X, n_clusters=2, linkage="single"):
    X = np.asarray(X, dtype=float)
    clusters = [[i] for i in range(len(X))]
    while len(clusters) > n_clusters:
        md, mi, mj = float("inf"), 0, 1
        for i in range(len(clusters)):
            for j in range(i + 1, len(clusters)):
                d = cluster_dist(X[clusters[i]], X[clusters[j]], linkage)
                if d < md:
                    md, mi, mj = d, i, j
        clusters[mi].extend(clusters[mj])
        clusters.pop(mj)
    labels = np.zeros(len(X), dtype=int)
    for cid, c in enumerate(clusters):
        for idx in c:
            labels[idx] = cid
    return labels.tolist()

# 持续合并至单簇并返回每步最小融合距离列表
def dendrogram_heights(X, linkage="single"):
    X = np.asarray(X, dtype=float)
    clusters = [[i] for i in range(len(X))]
    heights = []
    while len(clusters) > 1:
        md, mi, mj = float("inf"), 0, 1
        for i in range(len(clusters)):
            for j in range(i + 1, len(clusters)):
                d = cluster_dist(X[clusters[i]], X[clusters[j]], linkage)
                if d < md:
                    md, mi, mj = d, i, j
        heights.append(round(float(md), 4))
        clusters[mi].extend(clusters[mj])
        clusters.pop(mj)
    return heights

